    _MiddleCloudAltitude = (uLowestCloudAltitude + _HighestCloudAltitude) * 0.5;
    _HighestCloudRadius =_HighestCloudAltitude + _EarthRadius;
    _MiddleCloudRadius =_MiddleCloudAltitude + _EarthRadius;
