    var extentsLength = Layer.uClippingPolygonRegionsLength;
    var clippingDistanceTextureDimensions = vec2<f32>(textureDimensions(u_SignedDistanceTexture, 0));
    var sampleOffset = max(1.0 / clippingDistanceTextureDimensions, vec2(0.005));
    var dimension = f32(extentsLength);
    if (extentsLength > 2) {
       dimension = ceil(log2(f32(extentsLength)));
    }

    var textureOffset = vec2<f32>(f32(regionIndex) % dimension, floor(f32(regionIndex) / dimension)) / dimension;
